from common import *
from urllib.parse import quote
SCENE="<svg xmlns='http://www.w3.org/2000/svg' width='300' height='220' viewBox='0 0 300 220'><defs><linearGradient id='s' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#5dcbf1'/><stop offset='1' stop-color='#e5dcc2'/></linearGradient></defs><rect width='300' height='220' fill='url(#s)'/><rect y='140' width='300' height='80' fill='#7a9ba6'/><rect x='40' y='60' width='96' height='80' fill='none' stroke='#fff' stroke-width='4'/><circle cx='210' cy='150' r='14' fill='#fff'/><circle cx='170' cy='115' r='12' fill='#d74a23'/><rect x='160' y='127' width='20' height='30' fill='#d74a23'/></svg>"
SC='url(data:image/svg+xml;utf8,'+quote(SCENE,safe='')+')'
GR=lambda op:'url(data:image/svg+xml;utf8,'+quote(f"<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='matrix' values='0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 {op} 0'/></filter><rect width='100%' height='100%' filter='url(#n)'/></svg>",safe='')+')'
def photo(extra_style='',inner=''): return f'<div style="position:absolute;inset:0;background:{SC} center/cover;{extra_style}">{inner}</div>'
K1=f'<div class="t" style="height:230px">'+photo('', '<div style="position:absolute;inset:0;background:'+GR(.6)+'"></div><div style="position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 55%,rgba(6,21,14,.55) 100%)"></div>')+lab('K1','Filmkorrel en vignet')+'</div>'
K2=f'<div class="t" style="height:230px;background:var(--brand)"><div style="position:absolute;inset:0;background:{SC} center/cover;filter:grayscale(1) contrast(1.15);mix-blend-mode:multiply"></div>{lab("K2","Duotone in Soccer Green")}</div>'
strip=''.join(f'<div style="position:relative;flex:1;background:{SC} center/cover;margin:0 4px"><span class="eyebrow" style="position:absolute;left:4px;bottom:3px;font-size:9px;color:var(--surface);margin:0">0{i}</span></div>' for i in (1,2,3))
holes=lambda:'<div style="position:absolute;left:0;right:0;height:10px;display:flex;gap:10px;padding:0 6px">'+''.join('<i style="flex:1;height:10px;background:var(--surface)"></i>' for _ in range(16))+'</div>'
K3=f'<div class="t" style="height:230px;background:var(--ink)"><div style="position:absolute;left:0;right:0;top:50px;bottom:78px;background:var(--ink)"><div style="position:absolute;left:0;right:0;top:-24px">{holes()}</div><div style="position:absolute;left:0;right:0;top:0;bottom:0;display:flex;padding:0 2px">{strip}</div><div style="position:absolute;left:0;right:0;bottom:-24px">{holes()}</div></div>{lab("K3","Filmstrip met beeldnummers")}</div>'
K4=f'<div class="t l" style="height:230px;background:var(--surface-warm)"><div style="position:absolute;left:30px;right:30px;top:24px;height:128px;background:{SC} center/cover"></div><div style="position:absolute;left:30px;width:150px;top:160px;height:34px;background:linear-gradient(115deg,var(--aluminium-light),var(--aluminium-mid) 40%,var(--aluminium-light) 60%,var(--aluminium-mid));display:grid;place-items:center;clip-path:polygon(0 8px,8px 8px,8px 0,calc(100% - 8px) 0,calc(100% - 8px) 8px,100% 8px,100% calc(100% - 8px),calc(100% - 8px) calc(100% - 8px),calc(100% - 8px) 100%,8px 100%,8px calc(100% - 8px),0 calc(100% - 8px))"><span class="eyebrow" style="margin:0;font-size:10px;color:var(--aluminium-engrave);text-shadow:0 1px 0 rgba(255,255,255,.8)">Straatveld · 01</span></div>{lab("K4","Foto met aluminium onderschrift")}</div>'
K5=f'<div class="t" style="height:230px;background:var(--surface)"><div style="position:absolute;left:34px;right:34px;top:26px;bottom:48px;background:#fff;padding:12px 12px 36px;box-shadow:0 1px 0 rgba(0,0,0,.2)"><div style="width:100%;height:100%;background:{SC} center/cover"></div></div>{lab("K5","Afdruk met witte rand")}</div>'
K6=f'<div class="t" style="height:230px"><div style="position:absolute;inset:0;background:{SC} center/cover;filter:saturate(1.35) contrast(1.1) sepia(.12)"></div><div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(243,187,49,.4),transparent 55%)"></div>{lab("K6","Warm kleurfilm-gevoel")}</div>'
body=f'''<h2>K · Fotobehandeling en lijsten</h2><p class="note">Hoe beelden analoog aanvoelen zonder nep-vintage: korte korrel, duotone, filmstrip, afdruk met rand, aluminium onderschrift. De afbeeldingen hier zijn <b>plaatshouders</b> (een getekend veld), geen echte foto's. Geen sepia, geen verzonnen jaartallen.</p>
<div class="g">{K1}{K2}{K3}{K4}{K5}{K6}</div>'''
write('PhotoTreatments','Analoog: keuzes',720,body,'Optie-galerij K: fotobehandelingen en lijsten: K1 filmkorrel met vignet, K2 duotone in `brand`, K3 filmstrip met beeldnummers, K4 foto met aluminium onderschrift, K5 afdruk met witte rand, K6 warm kleurfilm-gevoel. De getekende scène is een plaatshouder. Campagnebeelden van echte foto\'s krijgen alleen K1 of K6 (subtiel); geen sepia en geen verzonnen jaartallen.\n')
